PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `kanji_catalog` (
	`id` integer PRIMARY KEY NOT NULL,
	`character` text NOT NULL,
	`meaning_pt` text NOT NULL,
	`onyomi` text,
	`kunyomi` text,
	`grade` integer NOT NULL,
	`jlpt_level` text,
	`full_words_json` text DEFAULT '[]' NOT NULL,
	CONSTRAINT "chk_kanji_catalog_grade" CHECK("kanji_catalog"."grade" BETWEEN 1 AND 6)
);
CREATE TABLE `kanji_practice_answers` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`session_id` text NOT NULL,
	`learner_id` text NOT NULL,
	`turn` integer NOT NULL,
	`kanji_id` integer NOT NULL,
	`result` text NOT NULL,
	`copies_before` integer NOT NULL,
	`copies_after` integer NOT NULL,
	`streak_before` integer NOT NULL,
	`streak_after` integer NOT NULL,
	`answered_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	FOREIGN KEY (`session_id`) REFERENCES `kanji_practice_sessions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`kanji_id`) REFERENCES `kanji_catalog`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "chk_kanji_answers_result" CHECK("kanji_practice_answers"."result" IN ('correct', 'wrong'))
);
CREATE TABLE `kanji_practice_sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`learner_id` text NOT NULL,
	`grouping` text NOT NULL,
	`level` text NOT NULL,
	`selected_ids_json` text NOT NULL,
	`selected_count` integer NOT NULL,
	`turn` integer DEFAULT 0 NOT NULL,
	`current_kanji_id` integer,
	`status` text DEFAULT 'active' NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	FOREIGN KEY (`current_kanji_id`) REFERENCES `kanji_catalog`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "chk_kanji_sessions_grouping" CHECK("kanji_practice_sessions"."grouping" IN ('jlpt', 'grade')),
	CONSTRAINT "chk_kanji_sessions_status" CHECK("kanji_practice_sessions"."status" IN ('active', 'completed', 'abandoned')),
	CONSTRAINT "chk_kanji_sessions_selected_count" CHECK("kanji_practice_sessions"."selected_count" >= 3)
);
CREATE TABLE `kanji_session_cooldowns` (
	`session_id` text NOT NULL,
	`kanji_id` integer NOT NULL,
	`blocked_until_turn` integer NOT NULL,
	PRIMARY KEY(`session_id`, `kanji_id`),
	FOREIGN KEY (`session_id`) REFERENCES `kanji_practice_sessions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`kanji_id`) REFERENCES `kanji_catalog`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `learner_kanji_progress` (
	`learner_id` text NOT NULL,
	`kanji_id` integer NOT NULL,
	`copies` integer DEFAULT 3 NOT NULL,
	`last_result` text,
	`streak` integer DEFAULT 0 NOT NULL,
	`correct_count` integer DEFAULT 0 NOT NULL,
	`wrong_count` integer DEFAULT 0 NOT NULL,
	`first_seen_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`last_seen_at` text,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	PRIMARY KEY(`learner_id`, `kanji_id`),
	FOREIGN KEY (`kanji_id`) REFERENCES `kanji_catalog`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "chk_learner_kanji_progress_copies" CHECK("learner_kanji_progress"."copies" BETWEEN 1 AND 8),
	CONSTRAINT "chk_learner_kanji_progress_streak" CHECK("learner_kanji_progress"."streak" BETWEEN 0 AND 1),
	CONSTRAINT "chk_learner_kanji_progress_result" CHECK("learner_kanji_progress"."last_result" IS NULL OR "learner_kanji_progress"."last_result" IN ('correct', 'wrong'))
);
ANALYZE sqlite_schema;
CREATE TABLE `learner_vocabulary_progress` (
	`learner_id` text NOT NULL,
	`vocabulary_id` integer NOT NULL,
	`direction` text NOT NULL,
	`copies` integer DEFAULT 3 NOT NULL,
	`last_result` text,
	`streak` integer DEFAULT 0 NOT NULL,
	`correct_count` integer DEFAULT 0 NOT NULL,
	`wrong_count` integer DEFAULT 0 NOT NULL,
	`first_seen_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`last_seen_at` text,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	PRIMARY KEY(`learner_id`, `vocabulary_id`, `direction`),
	FOREIGN KEY (`vocabulary_id`) REFERENCES `vocabulary_catalog`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "chk_learner_vocabulary_progress_direction" CHECK("learner_vocabulary_progress"."direction" IN ('pt_to_jp', 'jp_to_pt')),
	CONSTRAINT "chk_learner_vocabulary_progress_copies" CHECK("learner_vocabulary_progress"."copies" BETWEEN 1 AND 8),
	CONSTRAINT "chk_learner_vocabulary_progress_streak" CHECK("learner_vocabulary_progress"."streak" BETWEEN 0 AND 1),
	CONSTRAINT "chk_learner_vocabulary_progress_result" CHECK("learner_vocabulary_progress"."last_result" IS NULL OR "learner_vocabulary_progress"."last_result" IN ('correct', 'wrong'))
);
CREATE TABLE `vocabulary_catalog` (
	`id` integer PRIMARY KEY NOT NULL,
	`word` text NOT NULL,
	`reading` text NOT NULL,
	`meanings_pt_json` text NOT NULL,
	`meanings_en_json` text NOT NULL,
	`jlpt_level` text NOT NULL, `prompt_pt` text,
	CONSTRAINT "chk_vocabulary_catalog_jlpt" CHECK("vocabulary_catalog"."jlpt_level" IN ('N5', 'N4', 'N3', 'N2', 'N1')),
	CONSTRAINT "chk_vocabulary_catalog_meanings_pt" CHECK(json_valid("vocabulary_catalog"."meanings_pt_json")),
	CONSTRAINT "chk_vocabulary_catalog_meanings_en" CHECK(json_valid("vocabulary_catalog"."meanings_en_json"))
);
CREATE TABLE `vocabulary_practice_answers` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`session_id` text NOT NULL,
	`learner_id` text NOT NULL,
	`turn` integer NOT NULL,
	`vocabulary_id` integer NOT NULL,
	`direction` text NOT NULL,
	`result` text NOT NULL,
	`copies_before` integer NOT NULL,
	`copies_after` integer NOT NULL,
	`streak_before` integer NOT NULL,
	`streak_after` integer NOT NULL,
	`answered_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	FOREIGN KEY (`session_id`) REFERENCES `vocabulary_practice_sessions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`vocabulary_id`) REFERENCES `vocabulary_catalog`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "chk_vocabulary_answers_direction" CHECK("vocabulary_practice_answers"."direction" IN ('pt_to_jp', 'jp_to_pt')),
	CONSTRAINT "chk_vocabulary_answers_result" CHECK("vocabulary_practice_answers"."result" IN ('correct', 'wrong'))
);
CREATE TABLE `vocabulary_practice_sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`learner_id` text NOT NULL,
	`level` text NOT NULL,
	`direction` text NOT NULL,
	`show_furigana` integer DEFAULT false NOT NULL,
	`selected_ids_json` text NOT NULL,
	`selected_count` integer NOT NULL,
	`turn` integer DEFAULT 0 NOT NULL,
	`current_vocabulary_id` integer,
	`status` text DEFAULT 'active' NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	FOREIGN KEY (`current_vocabulary_id`) REFERENCES `vocabulary_catalog`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "chk_vocabulary_sessions_level" CHECK("vocabulary_practice_sessions"."level" IN ('N5', 'N4', 'N3', 'N2', 'N1')),
	CONSTRAINT "chk_vocabulary_sessions_direction" CHECK("vocabulary_practice_sessions"."direction" IN ('pt_to_jp', 'jp_to_pt')),
	CONSTRAINT "chk_vocabulary_sessions_status" CHECK("vocabulary_practice_sessions"."status" IN ('active', 'completed', 'abandoned')),
	CONSTRAINT "chk_vocabulary_sessions_selected_count" CHECK("vocabulary_practice_sessions"."selected_count" >= 3)
);
CREATE TABLE `vocabulary_session_cooldowns` (
	`session_id` text NOT NULL,
	`vocabulary_id` integer NOT NULL,
	`blocked_until_turn` integer NOT NULL,
	PRIMARY KEY(`session_id`, `vocabulary_id`),
	FOREIGN KEY (`session_id`) REFERENCES `vocabulary_practice_sessions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`vocabulary_id`) REFERENCES `vocabulary_catalog`(`id`) ON UPDATE no action ON DELETE cascade
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX `idx_kanji_catalog_character` ON `kanji_catalog` (`character`);
CREATE INDEX `idx_kanji_catalog_jlpt` ON `kanji_catalog` (`jlpt_level`,`id`);
CREATE INDEX `idx_kanji_catalog_grade` ON `kanji_catalog` (`grade`,`id`);
CREATE UNIQUE INDEX `idx_kanji_answers_session_turn` ON `kanji_practice_answers` (`session_id`,`turn`);
CREATE INDEX `idx_kanji_answers_learner_date` ON `kanji_practice_answers` (`learner_id`,`answered_at`);
CREATE INDEX `idx_kanji_sessions_learner_status` ON `kanji_practice_sessions` (`learner_id`,`status`,`updated_at`);
CREATE INDEX `idx_kanji_cooldowns_session_turn` ON `kanji_session_cooldowns` (`session_id`,`blocked_until_turn`);
CREATE INDEX `idx_learner_kanji_progress_learner` ON `learner_kanji_progress` (`learner_id`,`updated_at`);
CREATE INDEX `idx_learner_vocabulary_progress_learner` ON `learner_vocabulary_progress` (`learner_id`,`direction`,`updated_at`);
CREATE UNIQUE INDEX `idx_vocabulary_catalog_word_reading` ON `vocabulary_catalog` (`word`,`reading`);
CREATE INDEX `idx_vocabulary_catalog_jlpt` ON `vocabulary_catalog` (`jlpt_level`,`id`);
CREATE UNIQUE INDEX `idx_vocabulary_answers_session_turn` ON `vocabulary_practice_answers` (`session_id`,`turn`);
CREATE INDEX `idx_vocabulary_answers_learner_date` ON `vocabulary_practice_answers` (`learner_id`,`answered_at`);
CREATE INDEX `idx_vocabulary_sessions_learner_status` ON `vocabulary_practice_sessions` (`learner_id`,`status`,`updated_at`);
CREATE INDEX `idx_vocabulary_cooldowns_session_turn` ON `vocabulary_session_cooldowns` (`session_id`,`blocked_until_turn`);
CREATE TRIGGER `trg_validate_kanji_answer`
BEFORE INSERT ON `kanji_practice_answers`
FOR EACH ROW
WHEN NOT EXISTS (
	SELECT 1
	FROM `kanji_practice_sessions` AS session
	WHERE session.id = NEW.session_id
	  AND session.learner_id = NEW.learner_id
	  AND session.status = 'active'
	  AND session.turn = NEW.turn
	  AND session.current_kanji_id = NEW.kanji_id
)
BEGIN
	SELECT RAISE(ABORT, 'stale_kanji_answer');
END;
CREATE TRIGGER `trg_validate_vocabulary_answer`
BEFORE INSERT ON `vocabulary_practice_answers`
FOR EACH ROW
WHEN NOT EXISTS (
	SELECT 1
	FROM `vocabulary_practice_sessions` AS session
	WHERE session.id = NEW.session_id
	  AND session.learner_id = NEW.learner_id
	  AND session.direction = NEW.direction
	  AND session.status = 'active'
	  AND session.turn = NEW.turn
	  AND session.current_vocabulary_id = NEW.vocabulary_id
)
BEGIN
	SELECT RAISE(ABORT, 'stale_vocabulary_answer');
END;